    'fizz' => ['required', 'string'],
    'buzz' => ['required', 'numeric'],
    'foo' => ['required', 'string'],
    'bar' => [
        'required',
        'numeric',
        'gt:10',
        function (string $attribute, mixed $value, Closure $fail) {
