$validator->passes();

var_export($validator->errors()->messages());
echo PHP_EOL;

assert($validator->errors()->messages() === [
    'buzz' => ['buzz must be numeric'],
    'foo' => ['foo is required'],
    'bar' => ['bar must be odd'],
]);
echo "OK", PHP_EOL;
