use Illuminate\Support\Facades\Facade;
use Illuminate\Translation\ArrayLoader;
use Illuminate\Translation\Translator;
use Illuminate\Validation\Validator;

$container = new Container;
Facade::setFacadeApplication($container);
$container->singleton('translator', function () {
    return new Translator(new ArrayLoader, 'en');
});
$container->singleton('events', function () {
    return new \Illuminate\Events\Dispatcher;
});

$trans = $container->make('translator');

$data = [
    'fizz' => 'abc',
    'buzz' => 'xyz',
    'foo' => '',
    'bar' => '12',
];

$rules = [
    'fizz' => ['required', 'string'],
    'buzz' => ['required', 'numeric'],
    'foo' => ['required', 'string'],
    'bar' => [
        'required',
        'numeric',
        'gt:10',
        function (string $attribute, mixed $value, Closure $fail) {
            if ($value % 2 === 0) {
                $fail("{$attribute} must be odd");
            }
        },
    ],
];

$messages = [
    'fizz' => ['required' => 'fizz is required', 'string' => 'fizz must be a string'],
    'buzz' => ['required' => 'buzz is required', 'numeric' => 'buzz must be numeric'],
    'foo' => ['required' => 'foo is required', 'string' => 'foo must be a string'],
    'bar' => ['required' => 'bar is required', 'numeric' => 'bar must be numeric', 'gt' => 'bar must be greater than 10'],
];

$validator = new Validator($trans, $data, $rules, $messages);
$validator->passes();

var_export($validator->errors()->messages());
echo PHP_EOL;

assert($validator->errors()->messages() === [
    'buzz' => ['buzz must be numeric'],
    'foo' => ['foo is required'],
    'bar' => ['bar must be odd'],
]);
echo "OK", PHP_EOL;
EOF
